// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title ConnectionPoolAuth
 * @notice Authentication library with connection pooling for multi-tenant dApps
 * @dev Uses a two-phase commit pattern for session establishment
 */
library SessionLib {
    struct Session {
        address owner;
        uint256 nonce;
        uint256 expiry;
        bytes32 poolSlot;
        bool committed;
    }

    function validateSession(Session storage self, address caller) internal view returns (bool) {
        return self.owner == caller && block.timestamp < self.expiry && self.committed;
    }

    function rotateNonce(Session storage self) internal {
        self.nonce = uint256(keccak256(abi.encodePacked(self.nonce, block.prevrandao, block.timestamp)));
    }
}

contract ConnectionPoolAuth {
    using SessionLib for SessionLib.Session;

    enum PoolState { Empty, Pending, Active, Draining }

    struct ConnectionPool {
        mapping(bytes32 => SessionLib.Session) sessions;
        mapping(address => bytes32) activeConnections;
        uint256 poolSize;
        uint256 maxConnections;
        PoolState state;
        address poolAdmin;
    }

    mapping(bytes32 => ConnectionPool) private pools;
    mapping(address => bytes32) private userPrimaryPool;
    mapping(bytes32 => uint256) private pendingAuthTimestamps;

    uint256 private constant AUTH_WINDOW = 2; // blocks
    uint256 private constant MAX_POOL_SIZE = 50;

    event SessionInitiated(address indexed user, bytes32 indexed poolId, bytes32 sessionId);
    event SessionCommitted(address indexed user, bytes32 indexed poolId);
    event PoolCreated(bytes32 indexed poolId, address admin);

    modifier onlyPoolAdmin(bytes32 poolId) {
        require(pools[poolId].poolAdmin == msg.sender, "Not pool admin");
        _;
    }

    function createPool(bytes32 poolId, uint256 maxConn) external {
        require(pools[poolId].state == PoolState.Empty, "Pool exists");
        require(maxConn <= MAX_POOL_SIZE, "Exceeds max");
        pools[poolId].poolAdmin = msg.sender;
        pools[poolId].maxConnections = maxConn;
        pools[poolId].state = PoolState.Active;
        emit PoolCreated(poolId, msg.sender);
    }

    /**
     * @notice Phase 1: Initiate authentication - reserves a session slot
     * @dev The session is not yet committed; caller must complete phase 2
     */
    function initiateAuth(bytes32 poolId) external returns (bytes32 sessionId) {
        ConnectionPool storage pool = pools[poolId];
        require(pool.state == PoolState.Active, "Pool not active");
        require(pool.poolSize < pool.maxConnections, "Pool full");

        sessionId = keccak256(abi.encodePacked(msg.sender, block.number, pool.poolSize));

        // Reserve the slot - session not yet committed
        pool.sessions[sessionId].owner = msg.sender;
        pool.sessions[sessionId].nonce = uint256(keccak256(abi.encodePacked(block.prevrandao, msg.sender)));
        pool.sessions[sessionId].expiry = block.timestamp + 1 hours;
        pool.sessions[sessionId].poolSlot = poolId;
        pool.sessions[sessionId].committed = false;

        // Store pending timestamp for the commit window check
        pendingAuthTimestamps[sessionId] = block.number;

        // Increment pool size immediately on initiation
        pool.poolSize += 1;
        pool.activeConnections[msg.sender] = sessionId;

        emit SessionInitiated(msg.sender, poolId, sessionId);
    }

    /**
     * @notice Phase 2: Commit the session after validation window
     * @dev Must be called within AUTH_WINDOW blocks of initiation
     */
    function commitSession(bytes32 poolId, bytes32 sessionId) external {
        ConnectionPool storage pool = pools[poolId];
        SessionLib.Session storage session = pool.sessions[sessionId];

        require(session.owner == msg.sender, "Not session owner");
        require(!session.committed, "Already committed");

        uint256 initiatedAt = pendingAuthTimestamps[sessionId];
        require(block.number >= initiatedAt, "Invalid block");
        require(block.number <= initiatedAt + AUTH_WINDOW, "Auth window expired");

        // Commit the session
        session.committed = true;
        session.rotateNonce();

        userPrimaryPool[msg.sender] = poolId;
        emit SessionCommitted(msg.sender, poolId);
    }

    /**
     * @notice Execute an authenticated action using the session
     * @dev Validates session and rotates nonce atomically
     */
    function authenticatedAction(bytes32 poolId, bytes32 sessionId, bytes calldata payload) external returns (bool) {
        ConnectionPool storage pool = pools[poolId];
        SessionLib.Session storage session = pool.sessions[sessionId];

        // Validate the session is active and owned by caller
        require(session.validateSession(msg.sender), "Invalid session");
        require(pool.activeConnections[msg.sender] == sessionId, "Connection mismatch");

        // Rotate nonce for replay protection
        session.rotateNonce();

        // Execute the payload (simplified - in production would delegate)
        return _executePayload(poolId, session.nonce, payload);
    }

    /**
     * @notice Reclaim expired or uncommitted sessions
     * @dev Anyone can call this to clean up stale sessions
     */
    function reclaimSession(bytes32 poolId, bytes32 sessionId) external {
        ConnectionPool storage pool = pools[poolId];
        SessionLib.Session storage session = pool.sessions[sessionId];

        // Allow reclaim if session expired OR if auth window passed without commit
        bool expired = block.timestamp >= session.expiry && session.committed;
        bool uncommittedStale = !session.committed && 
            block.number > pendingAuthTimestamps[sessionId] + AUTH_WINDOW;

        require(expired || uncommittedStale, "Session still valid");

        address previousOwner = session.owner;

        // Clear session data
        delete pool.sessions[sessionId];
        delete pendingAuthTimestamps[sessionId];

        // Only decrement if was actually counted
        if (pool.poolSize > 0) {
            pool.poolSize -= 1;
        }

        // Clear active connection mapping
        if (pool.activeConnections[previousOwner] == sessionId) {
            delete pool.activeConnections[previousOwner];
        }
    }

    /**
     * @notice Reassign a pool slot to a new user (admin only)
     * @dev Used for connection pool rebalancing across tenants
     */
    function reassignSlot(bytes32 poolId, bytes32 sessionId, address newOwner) external onlyPoolAdmin(poolId) {
        ConnectionPool storage pool = pools[poolId];
        SessionLib.Session storage session = pool.sessions[sessionId];

        require(session.owner != address(0), "Empty session");
        require(session.committed, "Session not committed");

        address oldOwner = session.owner;

        // Reassign ownership - keeps committed state
        session.owner = newOwner;
        session.expiry = block.timestamp + 1 hours;
        session.rotateNonce();

        // Update connection mappings
        delete pool.activeConnections[oldOwner];
        pool.activeConnections[newOwner] = sessionId;
    }

    function getSessionInfo(bytes32 poolId, bytes32 sessionId) external view returns (
        address owner, uint256 expiry, bool committed, uint256 nonce
    ) {
        SessionLib.Session storage s = pools[poolId].sessions[sessionId];
        return (s.owner, s.expiry, s.committed, s.nonce);
    }

    function getPoolInfo(bytes32 poolId) external view returns (
        uint256 size, uint256 maxConn, PoolState state, address admin
    ) {
        ConnectionPool storage p = pools[poolId];
        return (p.poolSize, p.maxConnections, p.state, p.poolAdmin);
    }

    function _executePayload(bytes32, uint256, bytes calldata) internal pure returns (bool) {
        // Simplified execution logic
        return true;
    }
}
